o%CC%88nderisi%20(45)).png"},{"id":11,"category":"atolye","name":"Atölye Tam Set","description":"Hepsi bir arada","price":"₺7.999","image":"/media/woody/reference/m4z26p5k_2.png"},{"id":12,"category":"atolye","name":"Dijital Materyal","description":"Online erişim","price":"₺499","image":"/media/woody/reference/3jgyyil9_1.png"},{"id":13,"category":"ozel-ders","name":"Home Basic","description":"Bireysel başlangıç","price":"₺1.499","image":"/media/woody/reference/h5x59v59_3.png"},{"id":14,"category":"ozel-ders","name":"Home Junior","description":"Bireysel gelişim","price":"₺1.699","image":"/media/woody/reference/m4z26p5k_2.png"},{"id":15,"category":"ozel-ders","name":"Home Senior","description":"Bireysel ileri","price":"₺1.899","image":"/media/woody/reference/3jgyyil9_1.png"},{"id":16,"category":"ozel-ders","name":"Home PRO","description":"Bireysel profesyonel","price":"₺2.099","image":"/media/woody/reference/6qg348xf_Preschool%20Basic%20(297%20x%20210%20mm)%20(Instagram%20Go%CC%88nderisi%20(45)).png"},{"id":17,"category":"ozel-ders","name":"Özel Ders Paketi","description":"4 seviye kampanyalı","price":"₺5.999","image":"/media/woody/reference/h5x59v59_3.png"},{"id":18,"category":"ozel-ders","name":"Online Kütüphane","description":"Dijital erişim","price":"₺399","image":"/media/woody/reference/m4z26p5k_2.png"}]}'),
('ss-woody-page-preschool-tr', 'page_preschool', 'tr', '{"title":"{{appName}} Preschool Series","description":"{{appName}} Okul Serisi, kurumlara oyun temelli, planlı ve sürdürülebilir bir İngilizce eğitim altyapısı sunar.","eyebrow":"{{appName}} PRESCHOOL SERIES","hero":{"eyebrow":"{{appName}} PRESCHOOL SERIES","title":"Preschool","description":"{{appName}} Okul Serisi, kurumlara oyun temelli, planlı ve sürdürülebilir bir İngilizce eğitim altyapısı sunar.","primaryCTA":"Demo Talep Et","primaryHref":"/contact","secondaryCTA":"Fiyatları İncele","secondaryHref":"/fiyat"},"sections":[{"eyebrow":"Öğretmen ve Öğrenci Seti","title":"Okul Serisi iki ayrı setten oluşur","description":"Okul Serisi, Öğretmen Seti ve Öğrenci Seti olmak üzere iki ayrı setten oluşur. İçerikleri video anlatımlarıyla keşfedin. {{appName}} Preschool sisteminin uygulanabilmesi için kurum mevcudunun en az 30 öğrenci olması gerekmektedir. Öğretmen seti ayrıca ücretli olarak satılmaz. Anlaşma sağlanan kurumlara, öğrenci setleri ile birlikte ücretsiz olarak sunulur ve her sene yenilenir."},{"eyebrow":"Seviyeler","title":"Serilerin İçeriklerini Video Anlatımlarıyla Keşfedin","description":"Okul Serisi dört seviyeden oluşur: Basic, Junior, Senior ve PRO.","items":[{"badge":"BASIC","title":"Basic Level","description":"Temel kelimeler ve basit cümlelerle İngilizceye güçlü bir başlangıç sağlar."},{"badge":"JUNIOR","title":"Junior Level","description":"Çocukların cümle kurma ve kendini ifade etme becerilerini geliştirir."},{"badge":"SENIOR","title":"Senior Level","description":"İngilizceyi daha akıcı kullanma ve anlama becerisi kazandırır."},{"badge":"PRO","title":"PRO Level","description":"Okuma, yazma ve akademik İngilizce altyapısı oluşturur."}]},{"eyebrow":"Keşfet","title":"Sistemi Yakından İnceleyin","items":[{"title":"{{appName}} Level Finder","description":"Öğrencinin yaşını, İngilizce seviyesini ve öğrenme durumunu belirleyerek en uygun {{appName}} seviyesini hızlı ve doğru şekilde tespit etmenizi sağlar. Birkaç kısa soruya verilen cevaplara göre öğrencinin hangi seviyeden başlaması gerektiğini net olarak önerir.","href":"/level-finder"},{"title":"{{appName}} Library","description":"{{appName}} kitaplarını dijital ortamda inceleyebileceğiniz kütüphanedir. Tüm setleri detaylı şekilde görüntüleyebilir, içerikleri önceden inceleyerek sistem hakkında net fikir edinebilirsiniz.","href":"/library"},{"title":"{{appName}} Store","description":"{{appName}} setlerinin güncel fiyatlarını inceleyebileceğiniz ve online sipariş verebileceğiniz alandır.","href":"/store"}]}],"seo":{"title":"Anaokulu İngilizce Eğitim Setleri","description":"{{appName}} Preschool anaokulu İngilizce eğitim seti, 3-6 yaş çocuklar için oyun temelli okul öncesi İngilizce programı. Cambridge hazırlık sistemi ile preschool English curriculum. Öğretmen ve öğrenci setleri, anaokulu İngilizce müfredatı ve ders planı.","keywords":"anaokulu İngilizce eğitim seti, preschool English program Turkey, okul öncesi İngilizce seti, anaokulu için İngilizce programı, Cambridge hazırlık anaokulu, 3-6 yaş İngilizce programı, İngilizce eğitim serisi anaokulu"}}'),
('ss-woody-page-workshop-tr', 'page_workshop', 'tr', '{"title":"{{appName}} Workshop Series","description":"Atölye serisiyle çocuklar, İngilizceyi sadece dinlemez; oynar, uygular ve yaşar. {{appName}} ile daha canlı ve etkili bir öğrenme süreci sunun.","eyebrow":"{{appName}} WORKSHOP SERIES","hero":{"eyebrow":"{{appName}} WORKSHOP SERIES","title":"Workshop","description":"Atölye serisiyle çocuklar, İngilizceyi sadece dinlemez; oynar, uygular ve yaşar. {{appName}} ile daha canlı ve etkili bir öğrenme süreci sunun.","primaryCTA":"Demo Talep Et","primaryHref":"/contact","secondaryCTA":"Fiyatları İncele","secondaryHref":"/fiyat"},"sections":[{"eyebrow":"Seviyeler","title":"Serilerin İçeriklerini Video Anlatımlarıyla Keşfedin","description":"Atölye Serisi iki ayrı setten oluşur. İçerikleri video anlatımlarıyla keşfedin. Seriler dört seviyeden oluşur: Basic, Junior, Senior ve PRO.","items":[{"badge":"BASIC","title":"Basic Level","description":"Temel kelimeler ve basit cümlelerle İngilizceye güçlü bir başlangıç sağlar."},{"badge":"JUNIOR","title":"Junior Level","description":"Çocukların cümle kurma ve kendini ifade etme becerilerini geliştirir."},{"badge":"SENIOR","title":"Senior Level","description":"İngilizceyi daha akıcı kullanma ve anlama becerisi kazandırır."},{"badge":"PRO","title":"PRO Level","description":"Okuma, yazma ve akademik İngilizce altyapısı oluşturur."}]},{"eyebrow":"Keşfet","title":"Sistemi Yakından İnceleyin","items":[{"title":"{{appName}} Digital Library","description":"{{appName}} kitaplarını dijital ortamda inceleyebileceğiniz kütüphanedir. Tüm setleri detaylı şekilde görüntüleyebilir, içerikleri önceden inceleyerek sistem hakkında net fikir edinebilirsiniz.","href":"/library"},{"title":"{{appName}} Store","description":"{{appName}} setlerinin güncel fiyatlarını inceleyebileceğiniz ve online sipariş verebileceğiniz alandır.","href":"/store"}]}],"seo":{"title":"Workshop İngilizce Seti | Atölye Tabanlı Anaokulu İngilizce Eğitimi","description":"{{appName}} Workshop serisi: atölye tabanlı, uygulamalı anaokulu İngilizce eğitim seti. 4 seviye (Basic/Junior/Senior/PRO), oyun ve drama odaklı aktivitelerle çocuklar İngilizceyi yaşayarak öğrenir.","keywords":"workshop ingilizce seti, atölye tabanlı ingilizce, anaokulu ingilizce workshop, woody workshop, uygulamalı ingilizce eğitimi"}}'),
