INSERT INTO `site_settings` (`id`, `key`, `locale`, `value`) VALUES
('ss-woody-ui-cookie-tr', 'ui_cookie', 'tr', '{"cc_banner_title":"Çerezler","cc_banner_desc":"Deneyimi geliştirmek ve trafiği isteğe bağlı analiz etmek için çerezler kullanıyoruz.","cc_banner_link_policy":"Çerez Politikası","cc_banner_btn_settings":"Çerez Ayarları","cc_banner_btn_reject":"Tümünü Reddet","cc_banner_btn_accept":"Tümünü Kabul Et","cc_banner_aria_close":"Kapat","cc_banner_aria_region":"Çerez onayı","cc_title":"Çerez Ayarları","cc_description":"Hangi çerez kategorilerine izin vereceğinizi seçebilirsiniz. Zorunlu çerezler her zaman aktiftir.","cc_label_necessary":"Zorunlu","cc_desc_necessary":"Oturum, güvenlik ve dil tercihi gibi temel işlevler için gereklidir.","cc_label_analytics":"Analitik","cc_desc_analytics":"Trafiği ve performansı anlamamıza yardımcı olur.","cc_btn_cancel":"Vazgeç","cc_btn_save":"Kaydet","cc_aria_close":"Kapat","cc_pill_on":"Açık"}'),
('ss-woody-ui-cookie-en', 'ui_cookie', 'en', '{"cc_banner_title":"Cookies","cc_banner_desc":"We use cookies to improve your experience and optionally analyze traffic.","cc_banner_link_policy":"Cookie Policy","cc_banner_btn_settings":"Cookie Settings","cc_banner_btn_reject":"Reject All","cc_banner_btn_accept":"Accept All","cc_banner_aria_close":"Close","cc_banner_aria_region":"Cookie consent","cc_title":"Cookie Settings","cc_description":"You can choose which cookie categories you allow. Necessary cookies are always enabled.","cc_label_necessary":"Necessary","cc_desc_necessary":"Required for core functions such as session, security, and language preference.","cc_label_analytics":"Analytics","cc_desc_analytics":"Helps us understand traffic and performance.","cc_btn_cancel":"Cancel","cc_btn_save":"Save","cc_aria_close":"Close","cc_pill_on":"On"}'),
('ss-woody-ui-cookie-de', 'ui_cookie', 'de', '{"cc_banner_title":"Cookies","cc_banner_desc":"Wir verwenden Cookies, um Ihre Erfahrung zu verbessern und optional den Datenverkehr zu analysieren.","cc_banner_link_policy":"Cookie-Richtlinie","cc_banner_btn_settings":"Cookie-Einstellungen","cc_banner_btn_reject":"Alle ablehnen","cc_banner_btn_accept":"Alle akzeptieren","cc_banner_aria_close":"Schließen","cc_banner_aria_region":"Cookie-Einwilligung","cc_title":"Cookie-Einstellungen","cc_description":"Sie können auswählen, welche Cookie-Kategorien Sie erlauben. Notwendige Cookies sind immer aktiv.","cc_label_necessary":"Notwendig","cc_desc_necessary":"Erforderlich für Kernfunktionen wie Sitzung, Sicherheit und Spracheinstellung.","cc_label_analytics":"Analyse","cc_desc_analytics":"Hilft uns, Datenverkehr und Leistung zu verstehen.","cc_btn_cancel":"Abbrechen","cc_btn_save":"Speichern","cc_aria_close":"Schließen","cc_pill_on":"Aktiv"}'),
('ss-woody-ui-cookie-ar', 'ui_cookie', 'ar', '{"cc_banner_title":"ملفات تعريف الارتباط","cc_banner_desc":"نستخدم ملفات تعريف الارتباط لتحسين تجربتك وتحليل الزيارات اختياريا.","cc_banner_link_policy":"سياسة ملفات تعريف الارتباط","cc_banner_btn_settings":"إعدادات ملفات تعريف الارتباط","cc_banner_btn_reject":"رفض الكل","cc_banner_btn_accept":"قبول الكل","cc_banner_aria_close":"إغلاق","cc_banner_aria_region":"موافقة ملفات تعريف الارتباط","cc_title":"إعدادات ملفات تعريف الارتباط","cc_description":"يمكنك اختيار فئات ملفات تعريف الارتباط التي تسمح بها. الملفات الضرورية مفعلة دائما.","cc_label_necessary":"ضرورية","cc_desc_necessary":"ضروري للوظائف الأساسية مثل الجلسة والأمان وتفضيل اللغة.","cc_label_analytics":"التحليلات","cc_desc_analytics":"يساعدنا على فهم الزيارات والأداء.","cc_btn_cancel":"إلغاء","cc_btn_save":"حفظ","cc_aria_close":"إغلاق","cc_pill_on":"مفعل"}'),
('ss-woody-ui-cookie-fr', 'ui_cookie', 'fr', '{"cc_banner_title":"Cookies","cc_banner_desc":"Nous utilisons des cookies pour améliorer votre expérience et analyser le trafic de façon optionnelle.","cc_banner_link_policy":"Politique de cookies","cc_banner_btn_settings":"Paramètres des cookies","cc_banner_btn_reject":"Tout refuser","cc_banner_btn_accept":"Tout accepter","cc_banner_aria_close":"Fermer","cc_banner_aria_region":"Consentement aux cookies","cc_title":"Paramètres des cookies","cc_description":"Vous pouvez choisir les catégories de cookies autorisées. Les cookies nécessaires sont toujours actifs.","cc_label_necessary":"Nécessaires","cc_desc_necessary":"Nécessaire aux fonctions essentielles comme la session, la sécurité et la langue.","cc_label_analytics":"Analyse","cc_desc_analytics":"Nous aide à comprendre le trafic et les performances.","cc_btn_cancel":"Annuler","cc_btn_save":"Enregistrer","cc_aria_close":"Fermer","cc_pill_on":"Activé"}'),
('ss-woody-ui-cookie-ru', 'ui_cookie', 'ru', '{"cc_banner_title":"Cookies","cc_banner_desc":"Мы используем cookies, чтобы улучшить ваш опыт и при необходимости анализировать трафик.","cc_banner_link_policy":"Политика cookies","cc_banner_btn_settings":"Настройки cookies","cc_banner_btn_reject":"Отклонить все","cc_banner_btn_accept":"Принять все","cc_banner_aria_close":"Закрыть","cc_banner_aria_region":"Согласие на cookies","cc_title":"Настройки cookies","cc_description":"Вы можете выбрать разрешенные категории cookies. Необходимые cookies всегда включены.","cc_label_necessary":"Необходимые","cc_desc_necessary":"Необходимы для основных функций, таких как сессия, безопасность и выбор языка.","cc_label_analytics":"Аналитика","cc_desc_analytics":"Помогает нам понимать трафик и производительность.","cc_btn_cancel":"Отмена","cc_btn_save":"Сохранить","cc_aria_close":"Закрыть","cc_pill_on":"Вкл."}'),
('ss-woody-ui-cookie-es', 'ui_cookie', 'es', '{"cc_banner_title":"Cookies","cc_banner_desc":"Usamos cookies para mejorar tu experiencia y analizar el tráfico de forma opcional.","cc_banner_link_policy":"Política de cookies","cc_banner_btn_settings":"Configuración de cookies","cc_banner_btn_reject":"Rechazar todo","cc_banner_btn_accept":"Aceptar todo","cc_banner_aria_close":"Cerrar","cc_banner_aria_region":"Consentimiento de cookies","cc_title":"Configuración de cookies","cc_description":"Puedes elegir qué categorías de cookies permites. Las necesarias siempre están activas.","cc_label_necessary":"Necesarias","cc_desc_necessary":"Necesarias para funciones básicas como sesión, seguridad y preferencia de idioma.","cc_label_analytics":"Analítica","cc_desc_analytics":"Nos ayuda a entender el tráfico y el rendimiento.","cc_btn_cancel":"Cancelar","cc_btn_save":"Guardar","cc_aria_close":"Cerrar","cc_pill_on":"Activo"}'),
('ss-woody-ui-cookie-it', 'ui_cookie', 'it', '{"cc_banner_title":"Cookie","cc_banner_desc":"Usiamo i cookie per migliorare la tua esperienza e analizzare il traffico in modo facoltativo.","cc_banner_link_policy":"Informativa sui cookie","cc_banner_btn_settings":"Impostazioni cookie","cc_banner_btn_reject":"Rifiuta tutto","cc_banner_btn_accept":"Accetta tutto","cc_banner_aria_close":"Chiudi","cc_banner_aria_region":"Consenso ai cookie","cc_title":"Impostazioni cookie","cc_description":"Puoi scegliere quali categorie di cookie consentire. I cookie necessari sono sempre attivi.","cc_label_necessary":"Necessari","cc_desc_necessary":"Necessari per funzioni di base come sessione, sicurezza e preferenza lingua.","cc_label_analytics":"Analisi","cc_desc_analytics":"Ci aiuta a capire traffico e prestazioni.","cc_btn_cancel":"Annulla","cc_btn_save":"Salva","cc_aria_close":"Chiudi","cc_pill_on":"Attivo"}'),
('ss-woody-ui-cookie-nl', 'ui_cookie', 'nl', '{"cc_banner_title":"Cookies","cc_banner_desc":"We gebruiken cookies om je ervaring te verbeteren en optioneel verkeer te analyseren.","cc_banner_link_policy":"Cookiebeleid","cc_banner_btn_settings":"Cookie-instellingen","cc_banner_btn_reject":"Alles weigeren","cc_banner_btn_accept":"Alles accepteren","cc_banner_aria_close":"Sluiten","cc_banner_aria_region":"Cookie-toestemming","cc_title":"Cookie-instellingen","cc_description":"Je kunt kiezen welke cookiecategorieën je toestaat. Noodzakelijke cookies staan altijd aan.","cc_label_necessary":"Noodzakelijk","cc_desc_necessary":"Nodig voor kernfuncties zoals sessie, veiligheid en taalvoorkeur.","cc_label_analytics":"Analyse","cc_desc_analytics":"Helpt ons verkeer en prestaties te begrijpen.","cc_btn_cancel":"Annuleren","cc_btn_save":"Opslaan","cc_aria_close":"Sluiten","cc_pill_on":"Aan"}'),
('ss-woody-ui-cookie-ptbr', 'ui_cookie', 'pt-br', '{"cc_banner_title":"Cookies","cc_banner_desc":"Usamos cookies para melhorar sua experiência e analisar o tráfego opcionalmente.","cc_banner_link_policy":"Política de cookies","cc_banner_btn_settings":"Configurações de cookies","cc_banner_btn_reject":"Rejeitar tudo","cc_banner_btn_accept":"Aceitar tudo","cc_banner_aria_close":"Fechar","cc_banner_aria_region":"Consentimento de cookies","cc_title":"Configurações de cookies","cc_description":"Você pode escolher quais categorias de cookies permite. Cookies necessários ficam sempre ativos.","cc_label_necessary":"Necessários","cc_desc_necessary":"Necessário para funções básicas como sessão, segurança e preferência de idioma.","cc_label_analytics":"Análise","cc_desc_analytics":"Ajuda-nos a entender o tráfego e o desempenho.","cc_btn_cancel":"Cancelar","cc_btn_save":"Salvar","cc_aria_close":"Fechar","cc_pill_on":"Ativo"}'),
